// === Tab: mySketch ===
let myShader;

let vertShader = `
attribute vec3 aPosition;

attribute vec2 aTexCoord;

varying vec2 vTexCoord;

void main() {

  vTexCoord = aTexCoord;

  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

  gl_Position = positionVec4;
}
`;

let fragShader = `
#ifdef GL_ES
precision mediump float;
#endif

#define PI 3.1415926


uniform vec2 iResolution;
uniform float iTime;
uniform vec2 iMouse;

varying vec2 vTexCoord;

void main() {

  vec2 uv =  (2.0 * gl_FragCoord.xy - iResolution) / iResolution.y;

	uv *= 0.5;

  float a = fract((2.0 * PI + atan(uv.y, uv.x)) / (2.0 * PI));
  uv.x += uv.y * 0.15 * sin(uv.y * 8.0 + iTime);
  uv.y += uv.x * 0.15 * cos(uv.x * 8.0 + iTime);

  float l = length(uv)*sin(10.0);

  float d = fract((a + l * 8.0 - iTime / 4.0)*24.0);

  vec3 col = vec3(d) * vec3(fract(a + l * 8.0- iTime / 4.0)*2.0, fract(0.333 + a + l * 8.0- iTime / 4.0)*2.0, fract(0.667 + a + l * 8.0- iTime / 4.0)*2.0);

  // vec3 col = vec3(d);

  gl_FragColor = vec4(col, 1.0);
}
`;

function setup() {
  pixelDensity(2);

  createCanvas(1112, 834, WEBGL);
  myShader = createShader(vertShader, fragShader);
  noStroke();
}

function draw() {  
  shader(myShader);

  myShader.setUniform("iResolution", [width*2, height*2]);
  myShader.setUniform("iTime", millis() / 1000.0);
  myShader.setUniform("iMouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)]);

  rect(0,0,width, height);
}

function windowResized(){
  resizeCanvas(windowWidth, windowHeight);
}

